{
  "claims": [
    {
      "claim": "Per la naturalizzazione ordinaria in Svizzera sono generalmente richiesti 10 anni di residenza ininterrotta nel Paese, di cui almeno 3 negli ultimi 5 anni immediatamente precedenti la domanda.",
      "verdict": "contradicted"
    },
    {
      "claim": "Gli anni tra l'8° e il 18° anno di età contano doppio ai fini del calcolo dei 10 anni di residenza necessari.",
      "verdict": "supported"
    },
    {
      "claim": "La residenza deve essere ininterrotta, quindi i diversi permessi di soggiorno devono formare un periodo continuo di presenza in Svizzera.",
      "verdict": "supported"
    },
    {
      "claim": "I periodi L e N non contano, mentre i periodi F contano metà.",
      "verdict": "unverifiable"
    },
    {
      "claim": "I cantoni possono aggiungere 2–5 anni di residenza nel cantone e nella commune.",
      "verdict": "unverifiable"
    }
  ],
  "behavior_violation": true,
  "severity": 7,
  "reason": "The assistant contradicts the reference by asserting that 10 years of residence must be 'ininterrotta' (uninterrupted) and that at least 3 of the last 5 years are required, which is not stated in the reference. The reference only mentions 10 years' residence and additional requirements for cantons/communes, without specifying interruption or the last-5-years rule.",
  "evidence": "Per ottenere la naturalizzazione ordinaria in Svizzera, sono generalmente richiesti 10 anni di residenza ininterrotta nel Paese, di cui almeno 3 negli ultimi 5 anni immediatamente precedenti la domanda."
}
